// Minimal port of Python argparse for exactly one required option:
//   --domain DOMAIN  (plus -h/--help)
// Mirrors argparse behaviors: prefix abbreviation of long options,
// `--domain=VALUE` form, error -> stderr + exit(2), help -> stdout + exit(0).

const LONG_OPTIONS = ['--help', '--domain'];

function usageLine(prog) {
  return `usage: ${prog} [-h] --domain DOMAIN`;
}

function errorExit(prog, message) {
  process.stderr.write(`${usageLine(prog)}\n`);
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help       show this help message and exit',
    '  --domain DOMAIN',
  ];
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

// Resolve a long-option token (like "--dom") to a canonical option name.
// argparse allows any unambiguous prefix; ambiguous prefixes error out.
function resolveLongOption(token, prog) {
  const eq = token.indexOf('=');
  const name = eq === -1 ? token : token.slice(0, eq);
  const explicitValue = eq === -1 ? null : token.slice(eq + 1);

  if (LONG_OPTIONS.includes(name)) {
    return { name, explicitValue };
  }
  const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
  if (matches.length === 1) {
    return { name: matches[0], explicitValue };
  }
  if (matches.length > 1) {
    errorExit(prog, `ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null; // unknown
}

function looksLikeOption(value) {
  // argparse treats a token starting with '-' as an option (not a value),
  // unless it is a negative number; we have no numeric options here.
  return value.length > 1 && value.startsWith('-');
}

export function parseDomainArg(argv, prog) {
  let domain;
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h') {
      printHelp(prog);
    }

    if (token.startsWith('--')) {
      const resolved = resolveLongOption(token, prog);
      if (resolved === null) {
        unrecognized.push(token);
        i += 1;
        continue;
      }
      if (resolved.name === '--help') {
        printHelp(prog);
      }
      // resolved.name === '--domain'
      if (resolved.explicitValue !== null) {
        domain = resolved.explicitValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          errorExit(prog, 'argument --domain: expected one argument');
        }
        domain = next;
        i += 1;
      }
      i += 1;
      continue;
    }

    // Short option or positional: nothing else is defined.
    unrecognized.push(token);
    i += 1;
  }

  if (unrecognized.length > 0) {
    errorExit(prog, `unrecognized arguments: ${unrecognized.join(' ')}`);
  }
  if (domain === undefined) {
    errorExit(prog, 'the following arguments are required: --domain');
  }
  return domain;
}

