import { basename } from 'node:path';
import { parseDomainArg } from './argparse.mjs';
import { idnaEncode, idnaDecode, alabel, ulabel } from './idna.mjs';
import { pyBytesRepr } from './pyformat.mjs';

const prog = basename(process.argv[1]);
const domain = parseDomainArg(process.argv.slice(2), prog);

try {
  const encoded = idnaEncode(domain);
  console.log(pyBytesRepr(encoded));

  const decoded = idnaDecode(encoded);
  console.log(decoded);

  const firstLabel = domain.split('.')[0];
  if (firstLabel) {
    console.log(ulabel(idnaEncode(firstLabel)));
    console.log(pyBytesRepr(alabel(firstLabel)));
  }
} catch (err) {
  // Mimics the Python script dying with a traceback: message to stderr, RC=1.
  process.stderr.write(`${err.name}: ${err.message}\n`);
  process.exit(1);
}

