import { execFileSync } from 'node:child_process';

const cases = [
  [['--domain', 'example.com'], 0, 'example.com'],
  [['--domain=foo'], 0, 'foo'],
  [['--dom', 'bar'], 0, 'bar'],
  [['--d'], 2, null], // ambiguous? --d matches only --domain actually (--help starts with --h) -> should be 0... check below
  [['--domain'], 2, 'expected one argument'],
  [['--domain', '-x'], 2, 'expected one argument'],
  [['--domain=-x'], 0, '-x'],
  [[], 2, 'required: --domain'],
  [['--bogus'], 2, 'unrecognized arguments: --bogus'],
  [['--domain', 'a', 'extra'], 2, 'unrecognized arguments: extra'],
  [['-h'], 0, 'help'],
  [['--help'], 0, 'help'],
  [['--he'], 0, 'help'],
];

const harness = `import { parseDomainArg } from '/output/argparse.mjs';\nconst d = parseDomainArg(JSON.parse(process.argv[2]), 'prog');\nconsole.log('DOMAIN=' + d);`;

for (const [args, expectCode, expect] of cases) {
  let out = '', code = 0;
  try {
    out = execFileSync('node', ['--input-type=module', '-e', harness, JSON.stringify(args)], { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] });
  } catch (e) {
    code = e.status;
    out = (e.stdout || '') + (e.stderr || '');
  }
  const okCode = code === expectCode;
  const okMsg = expect === null || out.includes(expect.replace(/^DOMAIN=/, '')) || (expect === 'help' ? out.includes('options:') : out.includes(expect));
  console.log(`${okCode && okMsg ? 'PASS' : 'FAIL'} args=${JSON.stringify(args)} code=${code} out=${JSON.stringify(out.slice(0, 120))}`);
}

