// RFC 3492 punycode encoder/decoder, implemented from scratch.
// Parameters: base=36, tmin=1, tmax=26, skew=38, damp=700,
// initial_bias=72, initial_n=128, delimiter '-'.

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';

function adapt(delta, numPoints, firstTime) {
  delta = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  delta += Math.floor(delta / numPoints);
  let k = 0;
  while (delta > Math.floor(((BASE - TMIN) * TMAX) / 2)) {
    delta = Math.floor(delta / (BASE - TMIN));
    k += BASE;
  }
  return k + Math.floor(((BASE - TMIN + 1) * delta) / (delta + SKEW));
}

// digit 0-25 -> 'a'-'z', 26-35 -> '0'-'9'
function digitToBasic(d) {
  return String.fromCharCode(d + 22 + 75 * (d < 26));
}

function basicToDigit(cp) {
  if (cp >= 48 && cp < 58) return cp - 22; // '0'-'9'
  if (cp >= 65 && cp < 91) return cp - 65; // 'A'-'Z'
  if (cp >= 97 && cp < 123) return cp - 97; // 'a'-'z'
  return BASE; // invalid
}

export function punycodeEncode(label) {
  const cps = Array.from(label, (ch) => ch.codePointAt(0));
  let output = '';
  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;

  const basic = cps.filter((cp) => cp < 0x80);
  for (const cp of basic) output += String.fromCharCode(cp);
  const b = basic.length;
  let h = b;
  if (b > 0) output += DELIMITER;

  const len = cps.length;
  while (h < len) {
    let m = Infinity;
    for (const cp of cps) {
      if (cp >= n && cp < m) m = cp;
    }
    delta += (m - n) * (h + 1);
    n = m;
    for (const c of cps) {
      if (c < n) delta++;
      if (c === n) {
        let q = delta;
        for (let k = BASE; ; k += BASE) {
          const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
          if (q < t) break;
          output += digitToBasic(t + ((q - t) % (BASE - t)));
          q = Math.floor((q - t) / (BASE - t));
        }
        output += digitToBasic(q);
        bias = adapt(delta, h + 1, h === b);
        delta = 0;
        h++;
      }
    }
    delta++;
    n++;
  }
  return output;
}

export function punycodeDecode(ascii) {
  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  let d = ascii.lastIndexOf(DELIMITER);
  if (d < 0) d = 0;
  for (let j = 0; j < d; j++) {
    const cp = ascii.charCodeAt(j);
    if (cp >= 0x80) throw new Error('punycode: non-basic code point before delimiter');
    output.push(cp);
  }

  let index = d > 0 ? d + 1 : 0;
  while (index < ascii.length) {
    const oldi = i;
    let w = 1;
    for (let k = BASE; ; k += BASE) {
      if (index >= ascii.length) throw new Error('punycode: incomplete input');
      const digit = basicToDigit(ascii.charCodeAt(index++));
      if (digit >= BASE) throw new Error('punycode: invalid basic code point');
      i += digit * w;
      const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
      if (digit < t) break;
      w *= BASE - t;
    }
    bias = adapt(i - oldi, output.length + 1, oldi === 0);
    n += Math.floor(i / (output.length + 1));
    i = i % (output.length + 1);
    output.splice(i, 0, n);
    i++;
  }
  return String.fromCodePoint(...output);
}

