// Mimics Python's bytes.__repr__ for a string of "bytes" (ASCII chars).
// Wraps in b'...' using single quotes, switching to double quotes only when
// the content contains a single quote but no double quote. Escapes backslash,
// the active quote char, \t \n \r, and any byte <0x20 or >0x7e as \xHH.

export function pyBytesRepr(asciiString) {
  const hasSingle = asciiString.includes("'");
  const hasDouble = asciiString.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = 'b' + quote;
  for (const ch of asciiString) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (cp < 0x20 || cp > 0x7e) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

