node --input-type=module -e "
import { punycodeEncode, punycodeDecode } from '/output/punycode.mjs';
import { pyBytesRepr } from '/output/pyformat.mjs';

const vectors = [
  ['café', 'caf-dma'],
  ['προγραμματισμός', 'mxaae0anacrikcslm7j'],
  ['программирование', '80aafcnpc2aandfgoce'],
  ['рф', 'p1ai'],
  ['bücher', 'bcher-kva'],
];
let ok = true;
for (const [u, a] of vectors) {
  const enc = punycodeEncode(u);
