// IDNA (2008) layer — port of Python `idna` package semantics (idna/core.py).
// Pure ESM, zero external dependencies.

import { punycodeEncode, punycodeDecode } from './punycode.mjs';

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = 'IDNAError';
  }
}

export class InvalidCodepoint extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepoint';
  }
}

const ALABEL_PREFIX = 'xn--';

// U+002E, U+3002, U+FF0E, U+FF61
const UNICODE_DOTS_RE = /[.　．｡]/;

function isAscii(str) {
  for (const ch of str) {
    if (ch.codePointAt(0) >= 0x80) return false;
  }
  return true;
}

function checkLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }
  if (label[0] === '-' || label[label.length - 1] === '-') {
    throw new IDNAError('Label must not start or end with a hyphen');
  }
  let position = 0;
  for (const ch of label) {
    position += 1;
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      const ok =
        (cp >= 0x30 && cp <= 0x39) || // 0-9
        (cp >= 0x41 && cp <= 0x5a) || // A-Z
        (cp >= 0x61 && cp <= 0x7a) || // a-z
        cp === 0x2d; // '-'
      if (!ok) {
        const hex = cp.toString(16).toUpperCase().padStart(4, '0');
        throw new InvalidCodepoint(
          `Codepoint U+${hex} at position ${position} of '${label}' not allowed`
        );
      }
    }
    // Non-ASCII: accepted broadly (full IDNA2008 tables are out of scope).
  }
}

export function alabel(label) {
  if (isAscii(label)) {
    // Pure-ASCII label: validate via ulabel, keep the label unchanged.
    ulabel(label);
    if (label.length > 63) {
      throw new IDNAError('Label too long');
    }
    return label;
  }
  if (label.length === 0) {
    throw new IDNAError('No Input');
  }
  checkLabel(label);
  const ascii = ALABEL_PREFIX + punycodeEncode(label);
  if (ascii.length > 63) {
    throw new IDNAError('Label too long');
  }
  return ascii;
}

export function ulabel(labelAscii) {
  if (!isAscii(labelAscii)) {
    checkLabel(labelAscii);
    return labelAscii;
  }
  const label = labelAscii.toLowerCase();
  if (label.startsWith(ALABEL_PREFIX)) {
    let decoded;
    try {
      decoded = punycodeDecode(label.slice(ALABEL_PREFIX.length));
    } catch (err) {
      throw new IDNAError('Invalid A-label');
    }
    checkLabel(decoded);
    return decoded;
  }
  checkLabel(label);
  return label;
}

export function idnaEncode(domain) {
  if (typeof domain !== 'string' || domain.length === 0) {
    throw new IDNAError('Empty domain');
  }
  const labels = domain.split(UNICODE_DOTS_RE);
  while (labels.length > 0 && labels[0] === '') {
    labels.shift();
  }
  let trailingDot = false;
  if (labels.length > 0 && labels[labels.length - 1] === '') {
    labels.pop();
    trailingDot = true;
  }
  if (labels.length === 0) {
    throw new IDNAError('Empty domain');
  }
  const result = labels.map(alabel);
  if (trailingDot) {
    result.push('');
  }
  const ascii = result.join('.');
  if (ascii.length >= 253) {
    throw new IDNAError('Domain too long');
  }
  return ascii;
}

export function idnaDecode(domain) {
  if (typeof domain !== 'string' || domain.length === 0) {
    throw new IDNAError('Empty domain');
  }
  const labels = domain.split(UNICODE_DOTS_RE);
  while (labels.length > 0 && labels[0] === '') {
    labels.shift();
  }
  let trailingDot = false;
  if (labels.length > 0 && labels[labels.length - 1] === '') {
    labels.pop();
    trailingDot = true;
  }
  if (labels.length === 0) {
    throw new IDNAError('Empty domain');
  }
  const result = labels.map(ulabel);
  if (trailingDot) {
    result.push('');
  }
  return result.join('.');
}

