import {
  IDNAError,
  InvalidCodepoint,
  alabel,
  ulabel,
  idnaEncode,
  idnaDecode,
} from '/output/idna.mjs';

let failures = 0;
function eq(actual, expected, name) {
  if (actual === expected) {
    console.log(`PASS ${name}`);
  } else {
    failures++;
    console.log(`FAIL ${name}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throws(fn, msgPart, name) {
  try {
    fn();
    failures++;
    console.log(`FAIL ${name}: did not throw`);
  } catch (e) {
    if (e instanceof IDNAError && e.message.includes(msgPart)) {
      console.log(`PASS ${name} (${e.name}: ${e.message})`);
    } else {
      failures++;
      console.log(`FAIL ${name}: threw ${e.name}: ${e.message} (wanted IDNAError containing ${JSON.stringify(msgPart)})`);
    }
  }
}

// Basic round trips from the spec
eq(alabel('café'), 'xn--caf-dma', "alabel('café')");
eq(ulabel('xn--caf-dma'), 'café', "ulabel('xn--caf-dma')");
eq(alabel('EXAMPLE'), 'EXAMPLE', "alabel('EXAMPLE') keeps case");
eq(ulabel('EXAMPLE'), 'example', "ulabel('EXAMPLE') lowercases");
eq(ulabel('XN--CAF-DMA'), 'café', "ulabel('XN--CAF-DMA') lowercases before decode");

// Russian IDN
eq(idnaEncode('программирование.рф'), 'xn--80aafcnpc2aandfgoce.xn--p1ai', 'encode russian');
eq(idnaDecode('xn--80aafcnpc2aandfgoce.xn--p1ai'), 'программирование.рф', 'decode russian');

// Unicode dots (U+3002)
eq(idnaEncode('example。com'), 'example.com', 'unicode dot U+3002');
eq(idnaEncode('a．b｡c'), 'a.b.c', 'unicode dots U+FF0E U+FF61');

// ASCII passthrough / decode lowercasing
eq(idnaEncode('EXAMPLE.com'), 'EXAMPLE.com', 'encode keeps ASCII case');
eq(idnaDecode('EXAMPLE.com'), 'example.com', 'decode lowercases ASCII');
eq(idnaDecode('xn--caf-dma.fr'), 'café.fr', 'decode punycode label');
eq(idnaDecode('café.fr'), 'café.fr', 'decode unicode passthrough');

// Errors
throws(() => alabel('foo_bar'), "Codepoint U+005F at position 4 of 'foo_bar' not allowed", 'alabel invalid codepoint');
throws(() => idnaEncode('foo_bar.com'), "Codepoint U+005F at position 4 of 'foo_bar' not allowed", 'encode invalid codepoint');
throws(() => idnaEncode(''), 'Empty domain', 'empty domain encode');
throws(() => idnaDecode(''), 'Empty domain', 'empty domain decode');
throws(() => idnaEncode('...'), 'Empty domain', 'all dots');
throws(() => idnaEncode('a..b'), 'Empty Label', 'empty middle label');
throws(() => idnaEncode('-abc.com'), 'Label must not start or end with a hyphen', 'leading hyphen');
throws(() => idnaEncode('abc-.com'), 'Label must not start or end with a hyphen', 'trailing hyphen');
throws(() => idnaEncode('a'.repeat(64) + '.com'), 'Label too long', 'label too long');
throws(() => idnaEncode('é'.repeat(100)), 'Label too long', 'punycode label too long');
throws(() => idnaEncode('a b.com'), "Codepoint U+0020 at position 2 of 'a b' not allowed", 'space in label');
throws(() => ulabel('xn--zzzzzz'), 'Invalid A-label', 'invalid punycode decode');

// Trailing / leading dots
eq(idnaEncode('example.com.'), 'example.com.', 'trailing dot preserved on encode');
eq(idnaDecode('example.com.'), 'example.com.', 'trailing dot preserved on decode');
eq(idnaEncode('.example.com'), 'example.com', 'leading dot stripped');

// Domain too long: 4 labels of 63 + dots = 256
const longLabel = 'a'.repeat(63);
throws(() => idnaEncode([longLabel, longLabel, longLabel, longLabel].join('.')), 'Domain too long', 'domain too long');
// 63*3 + 2 dots + trailing dot handling
eq(idnaEncode([longLabel, longLabel, longLabel].join('.')), [longLabel, longLabel, longLabel].join('.'), '191-char domain ok');

// Error class hierarchy
try { alabel('foo_bar'); } catch (e) {
  if (e instanceof InvalidCodepoint && e instanceof IDNAError && e instanceof Error) {
    console.log('PASS InvalidCodepoint subclass hierarchy');
  } else { failures++; console.log('FAIL subclass hierarchy'); }
}

console.log(failures === 0 ? '\nALL TESTS PASSED' : `\n${failures} FAILURE(S)`);
process.exit(failures === 0 ? 0 : 1);

